CREATE OR REPLACE PROCEDURE sp(
  para_Age NUMBER,
  para_Name VARCHAR2,
  para_Party VARCHAR2,
  para_Home_city VARCHAR2
) AS
  CURSOR c_drivers IS
    SELECT *
    FROM driver
    WHERE Age > para_Age
      AND Party = para_Party;
  rec_driver driver%ROWTYPE;
BEGIN
  OPEN c_drivers;
  LOOP
    FETCH c_drivers INTO rec_driver;
    EXIT WHEN c_drivers%NOTFOUND;
    UPDATE driver
       SET Name = para_Name
     WHERE Driver_ID = rec_driver.Driver_ID;
  END LOOP;
  CLOSE c_drivers;

  DELETE FROM driver WHERE Party IS NULL;

  UPDATE driver
     SET Home_city = para_Home_city;

  UPDATE school_bus
     SET Years_Working = Years_Working + 1
   WHERE Driver_ID IN (SELECT Driver_ID FROM driver WHERE Party = para_Party);
END;

