  EXECUTE IMMEDIATE 'SELECT COUNT(*) FROM school_bus WHERE Years_Working <> 6' INTO v_count;
  IF v_count <> 0 THEN RAISE_APPLICATION_ERROR(-20004, ''bus count '' || v_count); END IF;
  EXECUTE IMMEDIATE 'DROP TABLE driver PURGE';
  EXECUTE IMMEDIATE 'DROP TABLE school_bus PURGE';
END;

